   "starters": {
    "ppu.cpp": "#include \"ppu.h\"\n\n// Write the Ppu member functions here. ppu.h lists them.\n",
    "cart.cpp": "#include \"cart.h\"\n\n// ---------- The cartridge ----------\n\nLoadResult Cartridge::load(const std::vector<std::uint8_t>& file) {\n    if (file.size() < 16) {\n        return LoadResult::TooShort;\n    }\n    if (file[0] != 'N' || file[1] != 'E' || file[2] != 'S' || file[3] != 0x1A) {\n        return LoadResult::NotInes;\n    }\n    int new_prg_banks = file[4];\n    int new_chr_banks = file[5];\n    std::uint8_t flags6 = file[6];\n    std::uint8_t flags7 = file[7];\n    std::size_t trainer = (flags6 & 0x04) ? 512 : 0;\n    std::size_t needed = 16 + trainer + new_prg_banks * 0x4000 + new_chr_banks * 0x2000;\n    if (file.size() < needed) {\n        return LoadResult::TooShort;\n    }\n    int new_mapper = (flags7 & 0xF0) | (flags6 >> 4);\n    if (new_mapper != 0) {\n        return LoadResult::UnsupportedMapper;\n    }\n\n    // Copy the ROMs into memory of our own, replacing any earlier cartridge.\n    auto rom = file.begin() + 16 + trainer;\n    auto chr_start = rom + new_prg_banks * 0x4000;\n    prg_.assign(rom, chr_start);\n    if (new_chr_banks) {\n        chr_.assign(chr_start, chr_start + new_chr_banks * 0x2000);\n    } else {\n        chr_.assign(0x2000, 0);                     // 8 KB of CHR RAM, cleared\n    }\n    chr_is_ram_ = new_chr_banks == 0;\n    prg_ram_.fill(0);\n\n    mapper_ = new_mapper;\n    prg_banks_ = new_prg_banks;\n    chr_banks_ = new_chr_banks;\n    mirroring_ = (flags6 & 0x01) ? Mirroring::Vertical : Mirroring::Horizontal;\n    battery_ = (flags6 & 0x02) != 0;\n    return LoadResult::Ok;\n}\n\nstd::uint8_t Cartridge::cpu_read(std::uint16_t addr) {\n    if (addr >= 0x6000 && addr < 0x8000) {\n        return prg_ram_[addr - 0x6000];\n    }\n    if (addr >= 0x8000 && !prg_.empty()) {\n        return prg_[(addr - 0x8000) % prg_.size()];\n    }\n    return 0;\n}\n\nvoid Cartridge::cpu_write(std::uint16_t addr, std::uint8_t value) {\n    if (addr >= 0x6000 && addr < 0x8000) {\n        prg_ram_[addr - 0x6000] = value;\n    }\n}\n\nstd::uint8_t Cartridge::ppu_read(std::uint16_t addr) {\n    if (chr_.empty()) {\n        return 0;\n    }\n    return chr_[addr & 0x1FFF];\n}\n\nvoid Cartridge::ppu_write(std::uint16_t addr, std::uint8_t value) {\n    if (chr_is_ram_) {\n        chr_[addr & 0x1FFF] = value;\n    }\n}\n"
   },
   "solution": {
    "ppu.cpp": "#include \"ppu.h\"\n\nvoid Ppu::reset() {\n    vram_.fill(0);\n    palette_ram_.fill(0);\n}\n\n// ---------- Memory ----------\n\nstd::uint16_t Ppu::nametable_index(std::uint16_t addr) const {\n    int offset = (addr - 0x2000) & 0x0FFF;          // 0000-0FFF: four 1 KB tables\n    int table = offset / 0x400;                     // 0, 1, 2 or 3\n    int physical;\n    if (cart_.mirroring() == Mirroring::Vertical) {\n        physical = table & 1;                       // 0 1 / 0 1\n    } else {\n        physical = table >> 1;                      // 0 0 / 1 1\n    }\n    return static_cast<std::uint16_t>(physical * 0x400 + (offset & 0x3FF));\n}\n\nint Ppu::palette_index(std::uint16_t addr) const {\n    int i = addr & 0x1F;\n    // 3F10, 3F14, 3F18 and 3F1C are the same bytes as 3F00, 3F04, 3F08, 3F0C.\n    if ((i & 0x13) == 0x10) {\n        i &= 0x0F;\n    }\n    return i;\n}\n\nstd::uint8_t Ppu::read(std::uint16_t addr) {\n    addr &= 0x3FFF;\n    if (addr < 0x2000) {\n        return cart_.ppu_read(addr);\n    }\n    if (addr < 0x3F00) {\n        return vram_[nametable_index(addr)];\n    }\n    return palette_ram_[palette_index(addr)];\n}\n\nvoid Ppu::write(std::uint16_t addr, std::uint8_t value) {\n    addr &= 0x3FFF;\n    if (addr < 0x2000) {\n        cart_.ppu_write(addr, value);\n    } else if (addr < 0x3F00) {\n        vram_[nametable_index(addr)] = value;\n    } else {\n        palette_ram_[palette_index(addr)] = value;\n    }\n}\n"
   },
   "harness": "#include <array>\n#include <cstdint>\n#include <cstdio>\n#include <fstream>\n#include <iostream>\n#include <iterator>\n#include <vector>\n#include \"cart.h\"\n#include \"ppu.h\"\nnamespace {\n\n// Builds a small iNES file in memory for the tests.\nstd::vector<std::uint8_t> make_rom(int prg_banks, int chr_banks, std::uint8_t flags6, std::uint8_t flags7) {\n    std::vector<std::uint8_t> f(16, 0);\n    f[0] = 'N'; f[1] = 'E'; f[2] = 'S'; f[3] = 0x1A;\n    f[4] = static_cast<std::uint8_t>(prg_banks);\n    f[5] = static_cast<std::uint8_t>(chr_banks);\n    f[6] = flags6;\n    f[7] = flags7;\n    if (flags6 & 0x04) f.resize(16 + 512, 0);\n    for (long i = 0; i < prg_banks * 0x4000L; i++) f.push_back(static_cast<std::uint8_t>(i * 7 + (i >> 8)));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) f.push_back(static_cast<std::uint8_t>(0xA0 ^ i ^ (i >> 4)));\n    return f;\n}\n\nstd::vector<std::uint8_t> read_file(const char* name) {\n    std::ifstream f(name, std::ios::binary);\n    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());\n}\n\nconst char* result_name(LoadResult r) {\n    switch (r) {\n    case LoadResult::Ok: return \"Ok\";\n    case LoadResult::NotInes: return \"NotInes\";\n    case LoadResult::TooShort: return \"TooShort\";\n    case LoadResult::UnsupportedMapper: return \"UnsupportedMapper\";\n    }\n    return \"?\";\n}\n\n}  // namespace\n\nCartridge cart;\nPpu ppu(cart);\n\nstatic void r(std::uint16_t a) { std::printf(\" %04X=%02X\", a, ppu.read(a)); }\n\nint main() {\n    int t = 0;\n    if (!(std::cin >> t)) return 1;\n    if (t == 1) {\n        cart.load(make_rom(1, 1, 0x01, 0));   // vertical\n        ppu.reset();\n        ppu.write(0x2000, 0x11); ppu.write(0x2400, 0x22); ppu.write(0x23FF, 0x33);\n        std::printf(\"vertical:\"); r(0x2800); r(0x2C00); r(0x2BFF); r(0x3000); r(0x3400); std::printf(\"\\n\");\n    }\n    if (t == 2) {\n        cart.load(make_rom(1, 1, 0x00, 0));   // horizontal\n        ppu.reset();\n        ppu.write(0x2000, 0x11); ppu.write(0x2800, 0x22); ppu.write(0x2FFF, 0x44);\n        std::printf(\"horizontal:\"); r(0x2400); r(0x2C00); r(0x2BFF); r(0x3BFF); std::printf(\"\\n\");\n    }\n    if (t == 3) {\n        cart.load(make_rom(1, 1, 0x01, 0));\n        ppu.reset();\n        ppu.write(0x3F00, 0x0F); ppu.write(0x3F14, 0x20); ppu.write(0x3F01, 0x16); ppu.write(0x3F11, 0x2A);\n        std::printf(\"palette:\"); r(0x3F10); r(0x3F04); r(0x3F01); r(0x3F11); r(0x3F20); r(0x3FF1); std::printf(\"\\n\");\n    }\n    if (t == 4) {\n        cart.load(make_rom(1, 1, 0x01, 0));\n        ppu.reset();\n        std::printf(\"patterns:\"); r(0x0000); r(0x0010); r(0x1FFF); r(0x4005);\n        ppu.write(0x0000, 0x77);\n        r(0x0000); std::printf(\"\\n\");\n        cart.load(make_rom(1, 0, 0x01, 0));\n        ppu.write(0x0000, 0x77);\n        std::printf(\"CHR RAM:\"); r(0x0000); std::printf(\"\\n\");\n    }\n    if (t == 5) {\n        cart.load(make_rom(1, 1, 0x01, 0));\n        ppu.reset();\n        ppu.write(0x2123, 0x99); ppu.write(0x3F05, 0x30);\n        ppu.reset();\n        std::printf(\"after reset:\"); r(0x2123); r(0x3F05); std::printf(\"\\n\");\n    }\n}\n",
