   "starters": {
    "ppu.cpp": "#include \"ppu.h\"\n\nvoid Ppu::reset() {\n    vram_.fill(0);\n    palette_ram_.fill(0);\n    ctrl_ = 0;\n    status_ = 0;\n    vram_addr_ = 0;\n    write_latch_ = false;\n    read_buffer_ = 0;\n}\n\n// ---------- Memory ----------\n\nstd::uint16_t Ppu::nametable_index(std::uint16_t addr) const {\n    int offset = (addr - 0x2000) & 0x0FFF;          // 0000-0FFF: four 1 KB tables\n    int table = offset / 0x400;                     // 0, 1, 2 or 3\n    int physical;\n    if (cart_.mirroring() == Mirroring::Vertical) {\n        physical = table & 1;                       // 0 1 / 0 1\n    } else {\n        physical = table >> 1;                      // 0 0 / 1 1\n    }\n    return static_cast<std::uint16_t>(physical * 0x400 + (offset & 0x3FF));\n}\n\nint Ppu::palette_index(std::uint16_t addr) const {\n    int i = addr & 0x1F;\n    // 3F10, 3F14, 3F18 and 3F1C are the same bytes as 3F00, 3F04, 3F08, 3F0C.\n    if ((i & 0x13) == 0x10) {\n        i &= 0x0F;\n    }\n    return i;\n}\n\nstd::uint8_t Ppu::read(std::uint16_t addr) {\n    addr &= 0x3FFF;\n    if (addr < 0x2000) {\n        return cart_.ppu_read(addr);\n    }\n    if (addr < 0x3F00) {\n        return vram_[nametable_index(addr)];\n    }\n    return palette_ram_[palette_index(addr)];\n}\n\nvoid Ppu::write(std::uint16_t addr, std::uint8_t value) {\n    addr &= 0x3FFF;\n    if (addr < 0x2000) {\n        cart_.ppu_write(addr, value);\n    } else if (addr < 0x3F00) {\n        vram_[nametable_index(addr)] = value;\n    } else {\n        palette_ram_[palette_index(addr)] = value;\n    }\n}\n\n// ---------- Tiles ----------\n\n// A tile is 16 bytes: 8 bytes for bit 0 of each pixel (one byte per row),\n// then 8 bytes for bit 1. In each byte, bit 7 is the leftmost pixel.\nstd::array<std::uint8_t, 8> Ppu::tile_row(std::uint16_t table, std::uint8_t tile, int row) {\n    auto base = static_cast<std::uint16_t>(table + tile * 16 + row);\n    std::uint8_t lo = read(base);\n    std::uint8_t hi = read(static_cast<std::uint16_t>(base + 8));\n    std::array<std::uint8_t, 8> out{};\n    for (int x = 0; x < 8; x++) {\n        int bit = 7 - x;\n        out[x] = static_cast<std::uint8_t>(((lo >> bit) & 1) | (((hi >> bit) & 1) << 1));\n    }\n    return out;\n}\n\n// ---------- The CPU's view: 2000-2007 ----------\n\nstd::uint8_t Ppu::register_read(int reg) {\n    switch (reg) {\n    case 2: {                                       // PPUSTATUS\n        auto value = static_cast<std::uint8_t>((status_ & 0xE0) | (read_buffer_ & 0x1F));\n        write_latch_ = false;                       // and resets the 2005/2006 latch\n        return value;\n    }\n    case 7: {                                       // PPUDATA\n        std::uint16_t addr = vram_addr_ & 0x3FFF;\n        std::uint8_t value;\n        if (addr >= 0x3F00) {\n            value = read(addr);                     // the palette answers at once\n            read_buffer_ = read(static_cast<std::uint16_t>(addr - 0x1000));\n        } else {\n            value = read_buffer_;                   // everything else is one read late\n            read_buffer_ = read(addr);\n        }\n        vram_addr_ = static_cast<std::uint16_t>((vram_addr_ + ((ctrl_ & 0x04) ? 32 : 1)) & 0x3FFF);\n        return value;\n    }\n    }\n    return 0;\n}\n\nvoid Ppu::register_write(int reg, std::uint8_t value) {\n    switch (reg) {\n    case 0:                                         // PPUCTRL\n        ctrl_ = value;\n        break;\n    case 6:                                         // PPUADDR: high byte, then low byte\n        if (!write_latch_) {\n            vram_addr_ = static_cast<std::uint16_t>(((value & 0x3F) << 8) | (vram_addr_ & 0x00FF));\n        } else {\n            vram_addr_ = static_cast<std::uint16_t>((vram_addr_ & 0xFF00) | value);\n        }\n        write_latch_ = !write_latch_;\n        break;\n    case 7:                                         // PPUDATA\n        write(vram_addr_, value);\n        vram_addr_ = static_cast<std::uint16_t>((vram_addr_ + ((ctrl_ & 0x04) ? 32 : 1)) & 0x3FFF);\n        break;\n    }\n}\n",
    "bus.cpp": "#include \"bus.h\"\n\nvoid Bus::reset() {\n    ram_.fill(0);\n}\n\nstd::uint8_t Bus::read(std::uint16_t addr) {\n    if (addr < 0x2000) {\n        return ram_[addr & 0x7FF];\n    }\n    if (addr >= 0x4020) {\n        return cart_.cpu_read(addr);\n    }\n    return 0;\n}\n\nvoid Bus::write(std::uint16_t addr, std::uint8_t value) {\n    if (addr < 0x2000) {\n        ram_[addr & 0x7FF] = value;\n    } else if (addr >= 0x4020) {\n        cart_.cpu_write(addr, value);\n    }\n}\n\nconst char* Bus::region(std::uint16_t addr) const {\n    if (addr < 0x2000) return \"RAM\";\n    if (addr < 0x4000) return \"PPU\";\n    if (addr < 0x4018) return \"APU/IO\";\n    if (addr < 0x4020) return \"Disabled\";\n    if (addr < 0x6000) return \"Expansion\";\n    if (addr < 0x8000) return \"Cartridge RAM\";\n    return \"Cartridge ROM\";\n}\n\nstd::uint16_t Bus::read16(std::uint16_t addr) {\n    std::uint16_t lo = read(addr);\n    std::uint16_t hi = read(static_cast<std::uint16_t>(addr + 1));\n    return static_cast<std::uint16_t>(hi << 8 | lo);\n}\n",
    "cart.cpp": "#include \"cart.h\"\n\n// ---------- The cartridge ----------\n\nLoadResult Cartridge::load(const std::vector<std::uint8_t>& file) {\n    if (file.size() < 16) {\n        return LoadResult::TooShort;\n    }\n    if (file[0] != 'N' || file[1] != 'E' || file[2] != 'S' || file[3] != 0x1A) {\n        return LoadResult::NotInes;\n    }\n    int new_prg_banks = file[4];\n    int new_chr_banks = file[5];\n    std::uint8_t flags6 = file[6];\n    std::uint8_t flags7 = file[7];\n    std::size_t trainer = (flags6 & 0x04) ? 512 : 0;\n    std::size_t needed = 16 + trainer + new_prg_banks * 0x4000 + new_chr_banks * 0x2000;\n    if (file.size() < needed) {\n        return LoadResult::TooShort;\n    }\n    int new_mapper = (flags7 & 0xF0) | (flags6 >> 4);\n    if (new_mapper != 0) {\n        return LoadResult::UnsupportedMapper;\n    }\n\n    // Copy the ROMs into memory of our own, replacing any earlier cartridge.\n    auto rom = file.begin() + 16 + trainer;\n    auto chr_start = rom + new_prg_banks * 0x4000;\n    prg_.assign(rom, chr_start);\n    if (new_chr_banks) {\n        chr_.assign(chr_start, chr_start + new_chr_banks * 0x2000);\n    } else {\n        chr_.assign(0x2000, 0);                     // 8 KB of CHR RAM, cleared\n    }\n    chr_is_ram_ = new_chr_banks == 0;\n    prg_ram_.fill(0);\n\n    mapper_ = new_mapper;\n    prg_banks_ = new_prg_banks;\n    chr_banks_ = new_chr_banks;\n    mirroring_ = (flags6 & 0x01) ? Mirroring::Vertical : Mirroring::Horizontal;\n    battery_ = (flags6 & 0x02) != 0;\n    return LoadResult::Ok;\n}\n\nstd::uint8_t Cartridge::cpu_read(std::uint16_t addr) {\n    if (addr >= 0x6000 && addr < 0x8000) {\n        return prg_ram_[addr - 0x6000];\n    }\n    if (addr >= 0x8000 && !prg_.empty()) {\n        return prg_[(addr - 0x8000) % prg_.size()];\n    }\n    return 0;\n}\n\nvoid Cartridge::cpu_write(std::uint16_t addr, std::uint8_t value) {\n    if (addr >= 0x6000 && addr < 0x8000) {\n        prg_ram_[addr - 0x6000] = value;\n    }\n}\n\nstd::uint8_t Cartridge::ppu_read(std::uint16_t addr) {\n    if (chr_.empty()) {\n        return 0;\n    }\n    return chr_[addr & 0x1FFF];\n}\n\nvoid Cartridge::ppu_write(std::uint16_t addr, std::uint8_t value) {\n    if (chr_is_ram_) {\n        chr_[addr & 0x1FFF] = value;\n    }\n}\n"
   },
