   "harness": "#include <array>\n#include <cstdint>\n#include <cstdio>\n#include <cstring>\n#include <fstream>\n#include <iostream>\n#include <iterator>\n#include <vector>\n#include \"bus.h\"\n#include \"cart.h\"\n#include \"cpu.h\"\n#include \"ppu.h\"\n#include \"palette.h\"\nnamespace {\n\n// Builds a small iNES file in memory for the tests.\nstd::vector<std::uint8_t> make_rom(int prg_banks, int chr_banks, std::uint8_t flags6, std::uint8_t flags7) {\n    std::vector<std::uint8_t> f(16, 0);\n    f[0] = 'N'; f[1] = 'E'; f[2] = 'S'; f[3] = 0x1A;\n    f[4] = static_cast<std::uint8_t>(prg_banks);\n    f[5] = static_cast<std::uint8_t>(chr_banks);\n    f[6] = flags6;\n    f[7] = flags7;\n    if (flags6 & 0x04) f.resize(16 + 512, 0);\n    for (long i = 0; i < prg_banks * 0x4000L; i++) f.push_back(static_cast<std::uint8_t>(i * 7 + (i >> 8)));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) f.push_back(static_cast<std::uint8_t>(0xA0 ^ i ^ (i >> 4)));\n    return f;\n}\n\nstd::vector<std::uint8_t> read_file(const char* name) {\n    std::ifstream f(name, std::ios::binary);\n    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());\n}\n\nconst char* result_name(LoadResult r) {\n    switch (r) {\n    case LoadResult::Ok: return \"Ok\";\n    case LoadResult::NotInes: return \"NotInes\";\n    case LoadResult::TooShort: return \"TooShort\";\n    case LoadResult::UnsupportedMapper: return \"UnsupportedMapper\";\n    }\n    return \"?\";\n}\n\n}  // namespace\n\nCartridge cart;\nPpu ppu(cart);\nBus bus(cart, ppu);\nCpu cpu(bus);\n\nnamespace {\n\n// Run Opcode's demo cartridge with scripted buttons.\nbool demo_start() {\n    std::vector<std::uint8_t> data = read_file(\"opcode-demo.nes\");\n    if (data.empty()) { std::printf(\"opcode-demo.nes is missing\\n\"); return false; }\n    LoadResult r = cart.load(data);\n    if (r != LoadResult::Ok) { std::printf(\"load returned LoadResult::%s\\n\", result_name(r)); return false; }\n    bus.reset();\n    ppu.reset();\n    cpu.reset();\n    return true;\n}\n\nvoid demo_frame() {\n    for (long cycles = 0; cycles < 200000; ) {\n        int c = cpu.step();\n        c += bus.take_stall();\n        cycles += c;\n        for (int i = 0; i < 3 * c; i++) ppu.tick();\n        if (ppu.take_nmi()) cpu.nmi();\n        if (ppu.take_frame()) break;\n    }\n}\n\n// The buttons for frame f of a walk to the right that jumps onto the chips.\nstd::uint8_t demo_buttons(int f) {\n    struct Step { int until; std::uint8_t buttons; };\n    const Step script[] = {\n        {30, 0}, {89, 0x80}, {92, 0x81}, {140, 0x80}, {143, 0x81}, {190, 0x80}, {193, 0x81},\n        {260, 0x82}, {263, 0x83}, {330, 0x82}, {333, 0x83}, {100000, 0x82},\n    };\n    int i = 0;\n    while (f > script[i].until) i++;\n    return script[i].buttons;                  // 80 Right, 01 A, 02 B: the order of controller.h\n}\n\n}  // namespace\n\nstatic void sprite(int i, int y, int x) {\n    ppu.register_write(3, static_cast<std::uint8_t>(i * 4));\n    ppu.register_write(4, static_cast<std::uint8_t>(y));\n    ppu.register_write(4, 1);\n    ppu.register_write(4, 0);\n    ppu.register_write(4, static_cast<std::uint8_t>(x));\n}\n\nstatic void hide_all() {\n    for (int i = 0; i < 64; i++) sprite(i, 0xFF, 0);\n}\n\nstatic void lines(int from, int to) {\n    for (int y = from; y <= to; y++) {\n        std::array<std::uint8_t, 8> found{};\n        int n = ppu.sprites_on_line(y, found);\n        std::printf(\"  line %3d: %d\", y, n);\n        for (int i = 0; i < (n > 8 ? 8 : n); i++) std::printf(\" %s%d\", i ? \"\" : \"[\", found[i]);\n        std::printf(\"%s\\n\", n ? \"]\" : \"\");\n    }\n}\n\nint main() {\n    int t = 0;\n    if (!(std::cin >> t)) return 1;\n    cart.load(make_rom(1, 1, 0x00, 0));\n    ppu.reset();\n    hide_all();\n    if (t == 1) {\n        sprite(5, 10, 40);\n        std::printf(\"sprite 5 at Y 10, 8 x 8:\\n\");\n        lines(9, 20);\n    }\n    if (t == 2) {\n        sprite(5, 10, 40);\n        ppu.register_write(0, 0x20);\n        std::printf(\"sprite 5 at Y 10, 8 x 16:\\n\");\n        lines(10, 28);\n    }\n    if (t == 3) {\n        for (int i = 0; i < 10; i++) sprite(3 + i * 5, 100 - (i % 3), i * 20);\n        std::printf(\"10 sprites near Y 100:\\n\");\n        lines(98, 103);\n    }\n    if (t == 4) {\n        sprite(0, 0x00, 0);\n        sprite(1, 0xEE, 0);\n        sprite(2, 0xEF, 0);\n        sprite(3, 0xF8, 0);\n        int lines_with[4] = {0};\n        for (int y = 0; y < 240; y++) {\n            std::array<std::uint8_t, 8> found{};\n            int n = ppu.sprites_on_line(y, found);\n            for (int i = 0; i < (n > 8 ? 8 : n); i++) lines_with[found[i]]++;\n        }\n        std::printf(\"lines showing sprite 0 (Y 00): %d, sprite 1 (Y EE): %d, sprite 2 (Y EF): %d, sprite 3 (Y F8): %d\\n\",\n                    lines_with[0], lines_with[1], lines_with[2], lines_with[3]);\n        std::array<std::uint8_t, 8> found{};\n        int line0 = ppu.sprites_on_line(0, found);\n        int line1 = ppu.sprites_on_line(1, found);\n        std::printf(\"line 0 has %d sprites, line 1 has %d\\n\", line0, line1);\n    }\n    if (t == 5) {\n        if (!demo_start()) return 0;\n        for (int f = 0; f < 60; f++) demo_frame();\n        std::printf(\"opcode-demo.nes after 60 frames, lines with sprites:\\n\");\n        int prev = -1, start = 0;\n        std::array<std::uint8_t, 8> prev_found{};\n        for (int y = 0; y <= 240; y++) {\n            std::array<std::uint8_t, 8> found{};\n            int n = y < 240 ? ppu.sprites_on_line(y, found) : -1;\n            if (n != prev || found != prev_found) {\n                if (prev > 0) {\n                    std::printf(\"  %3d-%3d: %d [\", start, y - 1, prev);\n                    for (int i = 0; i < (prev > 8 ? 8 : prev); i++) std::printf(\"%s%d\", i ? \" \" : \"\", prev_found[i]);\n                    std::printf(\"]\\n\");\n                }\n                prev = n;\n                prev_found = found;\n                start = y;\n            }\n        }\n    }\n}\n",
