   "harness": "#include <array>\n#include <cstdint>\n#include <cstdio>\n#include <cstring>\n#include <fstream>\n#include <iostream>\n#include <iterator>\n#include <vector>\n#include \"cart.h\"\n#include \"ppu.h\"\nnamespace {\n\n// Builds a small iNES file in memory for the tests.\nstd::vector<std::uint8_t> make_rom(int prg_banks, int chr_banks, std::uint8_t flags6, std::uint8_t flags7) {\n    std::vector<std::uint8_t> f(16, 0);\n    f[0] = 'N'; f[1] = 'E'; f[2] = 'S'; f[3] = 0x1A;\n    f[4] = static_cast<std::uint8_t>(prg_banks);\n    f[5] = static_cast<std::uint8_t>(chr_banks);\n    f[6] = flags6;\n    f[7] = flags7;\n    if (flags6 & 0x04) f.resize(16 + 512, 0);\n    for (long i = 0; i < prg_banks * 0x4000L; i++) f.push_back(static_cast<std::uint8_t>(i * 7 + (i >> 8)));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) f.push_back(static_cast<std::uint8_t>(0xA0 ^ i ^ (i >> 4)));\n    return f;\n}\n\nstd::vector<std::uint8_t> read_file(const char* name) {\n    std::ifstream f(name, std::ios::binary);\n    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());\n}\n\nconst char* result_name(LoadResult r) {\n    switch (r) {\n    case LoadResult::Ok: return \"Ok\";\n    case LoadResult::NotInes: return \"NotInes\";\n    case LoadResult::TooShort: return \"TooShort\";\n    case LoadResult::UnsupportedMapper: return \"UnsupportedMapper\";\n    }\n    return \"?\";\n}\n\n}  // namespace\n\nCartridge cart;\nPpu ppu(cart);\n\nnamespace {\n\n// A cartridge whose every byte says which bank it is in: PRG bytes hold\n// their 8 KB bank number, CHR bytes their 1 KB bank number.\nstd::vector<std::uint8_t> make_banked(int mapper, int prg16, int chr8, std::uint8_t mirror_bit) {\n    std::vector<std::uint8_t> f(16, 0);\n    f[0] = 'N'; f[1] = 'E'; f[2] = 'S'; f[3] = 0x1A;\n    f[4] = static_cast<std::uint8_t>(prg16);\n    f[5] = static_cast<std::uint8_t>(chr8);\n    f[6] = static_cast<std::uint8_t>(((mapper & 0x0F) << 4) | mirror_bit);\n    f[7] = static_cast<std::uint8_t>(mapper & 0xF0);\n    for (long o = 0; o < prg16 * 0x4000L; o++) f.push_back(static_cast<std::uint8_t>(o / 0x2000));\n    for (long o = 0; o < chr8 * 0x2000L; o++) f.push_back(static_cast<std::uint8_t>(o / 0x400));\n    return f;\n}\n\nvoid show_prg(const char* label) {\n    std::printf(\"%-24s 8000:%2d A000:%2d C000:%2d E000:%2d\\n\", label, cart.cpu_read(0x8000), cart.cpu_read(0xA000),\n                cart.cpu_read(0xC000), cart.cpu_read(0xE000));\n}\n\nvoid show_chr(const char* label) {\n    std::printf(\"%-24s\", label);\n    for (int i = 0; i < 8; i++) std::printf(\" %2d\", cart.ppu_read(static_cast<std::uint16_t>(i * 0x400)));\n    std::printf(\"\\n\");\n}\n\n}  // namespace\n\nnamespace {\n\nconst char* mirroring_name(Mirroring m) {\n    switch (m) {\n    case Mirroring::Horizontal: return \"horizontal\";\n    case Mirroring::Vertical: return \"vertical\";\n    case Mirroring::OneLow: return \"one-screen low\";\n    case Mirroring::OneHigh: return \"one-screen high\";\n    }\n    return \"?\";\n}\n\n}  // namespace\n\n// What a game does: five writes, bit 0 first, to the register's address.\nstatic void mmc1(std::uint16_t addr, std::uint8_t value) {\n    for (int i = 0; i < 5; i++) {\n        cart.cpu_write(addr, value);\n        value >>= 1;\n    }\n}\n\nint main() {\n    int t = 0;\n    if (!(std::cin >> t)) return 1;\n    std::printf(\"load: %s\\n\", result_name(cart.load(make_banked(1, 8, 4, 0))));\n    if (t == 1) {\n        show_prg(\"power on\");\n        mmc1(0xE000, 3);\n        show_prg(\"PRG bank 3 (mode 3)\");\n        mmc1(0x8000, 0x08);\n        show_prg(\"mode 2\");\n        mmc1(0x8000, 0x00);\n        show_prg(\"mode 0: 32 KB\");\n        mmc1(0xE000, 6);\n        show_prg(\"mode 0, bank 6\");\n        mmc1(0xFFFF, 13);\n        show_prg(\"bank 13 (wraps at 8)\");\n    }\n    if (t == 2) {\n        mmc1(0x8000, 0x0C);\n        mmc1(0xA000, 5);\n        mmc1(0xC000, 2);\n        show_chr(\"CHR mode 0, bank 5\");\n        mmc1(0x8000, 0x1C);\n        show_chr(\"CHR mode 1: 5 and 2\");\n        mmc1(0xDFFF, 7);\n        show_chr(\"second bank 7\");\n    }\n    if (t == 3) {\n        for (int m = 0; m < 4; m++) {\n            mmc1(0x8000, static_cast<std::uint8_t>(0x0C | m));\n            std::printf(\"control %02X: %s\\n\", 0x0C | m, mirroring_name(cart.mirroring()));\n        }\n    }\n    if (t == 4) {\n        cart.cpu_write(0xE000, 1);\n        cart.cpu_write(0xE000, 1);\n        cart.cpu_write(0xE000, 0x80);       // start again in the middle\n        show_prg(\"reset after two bits\");\n        mmc1(0xE000, 2);\n        show_prg(\"then five bits of 2\");\n        mmc1(0x8000, 0x00);\n        cart.cpu_write(0x8000, 0x80);       // a reset also sets PRG mode 3\n        show_prg(\"mode 0, then a reset\");\n    }\n    if (t == 5) {\n        ppu.reset();\n        const std::uint16_t at[4] = {0x2000, 0x2400, 0x2800, 0x2C00};\n        for (int m = 0; m < 4; m++) {\n            mmc1(0x8000, static_cast<std::uint8_t>(0x0C | m));\n            for (int i = 0; i < 4; i++) ppu.write(at[i], static_cast<std::uint8_t>(0x10 * m + i));\n            std::printf(\"%-16s 2000-2C00 read:\", mirroring_name(cart.mirroring()));\n            for (int i = 0; i < 4; i++) std::printf(\" %02X\", ppu.read(at[i]));\n            std::printf(\"\\n\");\n        }\n    }\n}\n",
